import { EssAuthError } from "./errors.js";
import { defaultStorage } from "../storage/browser-storage.js";
import type { EssAuthInitOptions, StorageLike } from "../../public/types.js";

const ESS_ORIGIN = "https://lynn-gray-frequent-attitude.trycloudflare.com";
const ESS_API_URL = `${ESS_ORIGIN}/api/v1`;
const ESS_LOGIN_URL = `${ESS_ORIGIN}/client-auth/login`;
const DEFAULT_STORAGE_KEY = "ess-auth-o1.client-identity.v1";
const PUBLIC_KEY_PATTERN = /^[A-Za-z0-9_-]{16}$/;

export interface ResolvedEssAuthConfig {
  publicKey: string;
  apiUrl: string;
  loginUrl: string;
  storage: StorageLike;
  storageKey: string;
  fetcher: typeof globalThis.fetch;
}

export function resolveConfig(options: EssAuthInitOptions): ResolvedEssAuthConfig {
  const publicKey = options.publicKey.trim();
  if (!PUBLIC_KEY_PATTERN.test(publicKey)) {
    throw new EssAuthError(
      "The registered client public key must contain exactly 16 URL-safe characters.",
      { code: "INVALID_CLIENT_PUBLIC_KEY" },
    );
  }

  const fetcher = options.fetch ?? globalThis.fetch;
  if (typeof fetcher !== "function") {
    throw new EssAuthError("A fetch implementation is required.", {
      code: "FETCH_REQUIRED",
    });
  }

  return {
    publicKey,
    apiUrl: ESS_API_URL,
    loginUrl: ESS_LOGIN_URL,
    storage: options.storage ?? defaultStorage(),
    storageKey:
      options.storageKey?.trim() || `${DEFAULT_STORAGE_KEY}.${publicKey}`,
    fetcher,
  };
}
